cat > $TMPDIR/m.py <<'E'
import re,os
T=os.environ.get('TMPDIR','/tmp')
a={};b={}
for l in open(T+'/a.txt'):
    m=re.match(r'\s+(\S+):(\d+)\s+<app-icon-button>',l)
    if m:a.setdefault(m[1],[]).append(int(m[2]))
for l in open(T+'/b.txt'):
    m=re.match(r'\s+(\S+):(\d+)\s+<app-icon-button>',l)
    if m:b.setdefault(m[1],[]).append(int(m[2]))
for f,ss in a.items():
    ss=sorted(ss);lab=set()
    for L in b.get(f,[]):
        s=max(x for x in ss if x<=L);lab.add(s)
    for s in ss:
        if s not in lab:
            print(f,s)
E
python3 $TMPDIR/m.py > $TMPDIR/missing.txt; wc -l $TMPDIR/missing.txt; while read f n; do echo "== $f:$n"; sed -n "${n},$((n+3))p" $f; done < $TMPDIR/missing.txt | head -150

